/// <summary>
/// PricingAttribute of table <c>CustTable</c> field EndDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, EndDisc))]
internal class GUPPricingAttributeCustTableEndDisc extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, EndDisc);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable       custTable;
    PriceDiscGroup  priceDiscGroup;

    while select EndDisc from custtable
        group by EndDisc
        join priceDiscGroup
        group by GroupId, Name, Module, Type
        where custTable.EndDisc == priceDiscGroup.GroupId && priceDiscGroup.Module  == ModuleInventCustVend::Cust &&
                  priceDiscGroup.Type == PriceGroupType::EndDiscGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
